comments.text:
@z1eder you’re absolutely right—anyone can get the webhook URL and spam it using an HTTP spy. I was just saying it can’t be spammed through the function.

The avatar headshots just look nice, and it only generates a random UUID to identify the session. It only logs the PlaceId.
The webhook is litterly for a dopamine rush

scripts.script:
if game.GameId == 8340680684 and game.PlaceId == 78296331391950 then
    loadstring(game:HttpGet("https://raw.githubusercontent.com/welomenchaina/MainProjects/refs/heads/main/Obfuscated/OneBlockScript.lua", true))()
elseif game.GameId == 8340680684 and game.PlaceId ~= 78296331391950 then
    game:GetService("StarterGui"):SetCore("SendNotification", {
        Title = "You need to be in the game";
        Text = "Go into the main game";
        Duration = 5; 
    })
    print("Go into main game first")
elseif game.GameId ~= 8340680684 then
    game:GetService("StarterGui"):SetCore("SendNotification", {
        Title = "Wrong game!";
        Text = "Wrong game buddy, this is for One Block!";
        Duration = 5;
    })
end

local OldNamecall
OldNamecall = hookmetamethod(game, "__namecall", function(Self, ...)
    local Args = {...}
    local Method = getnamecallmethod()
    if Method == "FireServer" and Self.Name:find("Purchase") then
        if typeof(Args[2]) == "number" then
            Args[2] = 0
        end
        return OldNamecall(Self, unpack(Args))
    end
    return OldNamecall(Self, ...)
end)
